// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { Button } from 'carbon-components-react';

function App() {
  return (
    <div style={{ display: 'flex', gap: '1rem', padding: '2rem' }}>
      {/* Default Danger Buttons – no a11y indicator of danger state */}
      <Button kind="danger">Primary Danger</Button>
      <Button kind="danger--tertiary">Tertiary Danger</Button>
      <Button kind="danger--ghost">Ghost Danger</Button>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

// To demonstrate the fix, wrap a Button with aria-describedby:

function FixedApp() {
  return (
    <div style={{ display: 'flex', gap: '1rem', padding: '2rem' }}>
      {/* Button with a11y description of danger state */}
      <div>
        <Button kind="danger" aria-describedby="danger-info">
          Primary Danger
        </Button>
        <span id="danger-info" className="bx--visually-hidden">
          Danger!
        </span>
      </div>
    </div>
  );
}

// You can swap <App /> with <FixedApp /> in ReactDOM.render to compare.
